import { describe, it, expect } from "vitest";
import { filterEnvAllowlist } from "../../packages/env";

describe("filterEnvAllowlist", () => {
  it("passes through allowed keys", () => {
    const env = { PATH: "/usr/bin", HOME: "/home/user", SECRET_TOKEN: "abc123" };
    const result = filterEnvAllowlist(env as NodeJS.ProcessEnv);
    expect(result.PATH).toBe("/usr/bin");
    expect(result.HOME).toBe("/home/user");
    expect(result).not.toHaveProperty("SECRET_TOKEN");
  });

  it("is case-insensitive for key matching", () => {
    const env = { path: "/usr/bin", Path: "/usr/bin2" };
    const result = filterEnvAllowlist(env as NodeJS.ProcessEnv);
    // Both should be included since they match PATH case-insensitively
    expect(Object.keys(result).length).toBeGreaterThanOrEqual(1);
  });

  it("skips undefined values", () => {
    const env = { PATH: undefined, HOME: "/home" } as unknown as NodeJS.ProcessEnv;
    const result = filterEnvAllowlist(env);
    expect(result).not.toHaveProperty("PATH");
    expect(result.HOME).toBe("/home");
  });

  it("supports additional keys", () => {
    const env = { PATH: "/usr/bin", CUSTOM_VAR: "custom" };
    const result = filterEnvAllowlist(env as NodeJS.ProcessEnv, ["CUSTOM_VAR"]);
    expect(result.CUSTOM_VAR).toBe("custom");
  });

  it("returns empty object for empty env", () => {
    const result = filterEnvAllowlist({} as NodeJS.ProcessEnv);
    expect(Object.keys(result)).toHaveLength(0);
  });

  it("filters out sensitive variables", () => {
    const env = {
      PATH: "/usr/bin",
      AWS_SECRET_ACCESS_KEY: "secret",
      GITHUB_TOKEN: "ghp_xxx",
      DATABASE_URL: "postgres://...",
      NODE_ENV: "production",
    };
    const result = filterEnvAllowlist(env as NodeJS.ProcessEnv);
    expect(result.PATH).toBe("/usr/bin");
    expect(result.NODE_ENV).toBe("production");
    expect(result).not.toHaveProperty("AWS_SECRET_ACCESS_KEY");
    expect(result).not.toHaveProperty("GITHUB_TOKEN");
    expect(result).not.toHaveProperty("DATABASE_URL");
  });
});

describe("filterEnvAllowlist — network / tooling variables", () => {
  it("forwards proxy variables in upper and lower case", () => {
    const result = filterEnvAllowlist({
      HTTP_PROXY: "http://proxy:3128",
      https_proxy: "http://proxy:3128",
      no_proxy: "localhost",
    } as NodeJS.ProcessEnv);
    expect(result.HTTP_PROXY).toBe("http://proxy:3128");
    expect(result.https_proxy).toBe("http://proxy:3128");
    expect(result.no_proxy).toBe("localhost");
  });

  it("forwards NODE_EXTRA_CA_CERTS, PLAYWRIGHT_BROWSERS_PATH and CI", () => {
    const result = filterEnvAllowlist({
      NODE_EXTRA_CA_CERTS: "/etc/ca.pem",
      PLAYWRIGHT_BROWSERS_PATH: "/ms-playwright",
      CI: "true",
    } as NodeJS.ProcessEnv);
    expect(result).toEqual({
      NODE_EXTRA_CA_CERTS: "/etc/ca.pem",
      PLAYWRIGHT_BROWSERS_PATH: "/ms-playwright",
      CI: "true",
    });
  });

  it("still blocks tokens", () => {
    const result = filterEnvAllowlist({ NPM_TOKEN: "x", GITHUB_TOKEN: "y" } as NodeJS.ProcessEnv);
    expect(result).toEqual({});
  });
});
